-- ---------------------------------------------------------------------------
-- 0001 — Core schema
--
-- Design notes:
--  * Every shared row carries couple_id so a single membership check protects
--    the whole space.
--  * Primary keys on messages/events are generated by the *client* so that
--    retrying an offline write is idempotent by construction.
--  * Deletions are tombstones (deleted_at) so offline devices can learn about
--    them. A hard delete would be invisible to a device that was away.
--  * All-day events use `date`, timed events use `timestamptz` + IANA zone.
--    Mixing the two is the classic source of off-by-one-day bugs.
-- ---------------------------------------------------------------------------

create extension if not exists pgcrypto;

-- Private space -------------------------------------------------------------

create table public.couples (
  id          uuid primary key default gen_random_uuid(),
  name        text check (name is null or length(btrim(name)) between 1 and 60),
  created_at  timestamptz not null default now()
);

create table public.couple_members (
  couple_id  uuid not null references public.couples(id) on delete cascade,
  user_id    uuid not null references auth.users(id) on delete cascade,
  joined_at  timestamptz not null default now(),
  primary key (couple_id, user_id)
);

-- Only the leading column of a btree index is usable for lookups, so
-- "which space am I in?" needs its own index on user_id.
create index couple_members_user_id_idx on public.couple_members (user_id);

-- A user may belong to at most one private space.
create unique index couple_members_one_space_per_user_idx
  on public.couple_members (user_id);

-- Invitations ---------------------------------------------------------------

create table public.invitations (
  id          uuid primary key default gen_random_uuid(),
  couple_id   uuid not null references public.couples(id) on delete cascade,
  code_hash   text not null unique,
  created_by  uuid not null references auth.users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null,
  used_at     timestamptz,
  used_by     uuid references auth.users(id),
  revoked_at  timestamptz
);

create index invitations_couple_id_idx on public.invitations (couple_id);

-- Chat ----------------------------------------------------------------------

create table public.messages (
  id                 uuid primary key,
  couple_id          uuid not null references public.couples(id) on delete cascade,
  sender_id          uuid not null references auth.users(id) on delete cascade,
  body               text not null check (length(body) between 1 and 4000),
  client_created_at  timestamptz not null,
  server_created_at  timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  deleted_at         timestamptz
);

create index messages_couple_created_idx
  on public.messages (couple_id, server_created_at desc);

create index messages_couple_updated_idx
  on public.messages (couple_id, updated_at desc);

-- Calendar ------------------------------------------------------------------

create table public.events (
  id                uuid primary key,
  couple_id         uuid not null references public.couples(id) on delete cascade,
  created_by        uuid not null references auth.users(id) on delete cascade,
  title             text not null check (length(btrim(title)) between 1 and 200),
  description       text check (description is null or length(description) <= 4000),
  location          text check (location is null or length(location) <= 300),
  all_day           boolean not null default false,
  starts_on         date,
  ends_on           date,
  starts_at         timestamptz,
  ends_at           timestamptz,
  timezone          text,
  visibility        text not null default 'shared'
                      check (visibility in ('shared', 'private')),
  category          text,
  color             text check (color is null or color ~ '^#[0-9A-Fa-f]{6}$'),
  reminder_minutes  integer[] not null default '{}',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,

  -- An event is either all-day (calendar dates) or timed (instants). Never both.
  constraint events_time_shape check (
    (all_day and starts_on is not null and ends_on is not null
             and starts_at is null and ends_at is null)
    or
    (not all_day and starts_at is not null and ends_at is not null
                 and starts_on is null and ends_on is null)
  ),
  constraint events_time_order check (
    (all_day and ends_on >= starts_on)
    or
    (not all_day and ends_at >= starts_at)
  ),
  constraint events_timezone_required check (
    all_day or (timezone is not null and length(timezone) between 1 and 64)
  )
);

create index events_couple_starts_idx
  on public.events (couple_id, starts_at);

create index events_couple_starts_on_idx
  on public.events (couple_id, starts_on);

create index events_couple_updated_idx
  on public.events (couple_id, updated_at desc);

-- Push tokens ---------------------------------------------------------------

create table public.push_tokens (
  expo_token  text primary key,
  user_id     uuid not null references auth.users(id) on delete cascade,
  couple_id   uuid not null references public.couples(id) on delete cascade,
  platform    text not null default 'android',
  updated_at  timestamptz not null default now()
);

create index push_tokens_couple_idx on public.push_tokens (couple_id);
